#!/usr/bin/env python3
"""Durable record store served on port 8080.

GET  /health            -> 200 "ready"
PUT  /records/<id>      -> 204 (stores request body verbatim)
GET  /records/<id>      -> 200 (returns the exact stored body)

Records live under DATA_DIR and survive process restarts and host reboots
because the host's root filesystem is on /dev/vda (ext4, rw).
"""

import os
import re
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DATA_DIR = os.environ.get("BUILDER_DATA_DIR", "/var/lib/builder/records")
LISTEN_HOST = os.environ.get("BUILDER_HOST", "0.0.0.0")
LISTEN_PORT = int(os.environ.get("BUILDER_PORT", "8080"))

os.makedirs(DATA_DIR, exist_ok=True)

SAFE_ID = re.compile(r"^[A-Za-z0-9._-]{1,200}$")

_lock = threading.Lock()


def record_path(record_id: str) -> str:
    return os.path.join(DATA_DIR, record_id)


def store_record(record_id: str, body: bytes) -> None:
    target = record_path(record_id)
    tmp = target + ".tmp." + str(os.getpid()) + "." + str(threading.get_ident())
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
    try:
        os.write(fd, body)
        os.fsync(fd)
    finally:
        os.close(fd)
    os.replace(tmp, target)
    dfd = os.open(DATA_DIR, os.O_RDONLY)
    try:
        os.fsync(dfd)
    finally:
        os.close(dfd)


def load_record(record_id: str):
    try:
        with open(record_path(record_id), "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        return None


class Handler(BaseHTTPRequestHandler):
    server_version = "BuilderApp/1.0"

    def log_message(self, fmt, *args):
        sys.stderr.write("[%s] %s\n" % (self.log_date_time_string(), fmt % args))
        sys.stderr.flush()

    def _send(self, status, body=b"", content_type="text/plain; charset=utf-8"):
        self.send_response(status)
        if body:
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _id_from_path(self):
        path = self.path
        if not path.startswith("/records/"):
            return None
        rest = path[len("/records/"):]
        if not rest:
            return None
        for sep in ("?", "#"):
            if sep in rest:
                rest = rest.split(sep, 1)[0]
        if "/" in rest:
            return None
        if not SAFE_ID.match(rest):
            return None
        return rest

    def do_GET(self):
        if self.path == "/health":
            self._send(200, b"ready")
            return
        record_id = self._id_from_path()
        if record_id is None:
            self._send(404, b"not found")
            return
        with _lock:
            body = load_record(record_id)
        if body is None:
            self._send(404, b"not found")
            return
        self._send(200, body, content_type="application/octet-stream")

    def do_PUT(self):
        record_id = self._id_from_path()
        if record_id is None:
            self._send(404, b"not found")
            return
        length_hdr = self.headers.get("Content-Length")
        if length_hdr is None:
            self._send(411, b"length required")
            return
        try:
            length = int(length_hdr)
        except ValueError:
            self._send(400, b"bad length")
            return
        if length < 0:
            self._send(400, b"bad length")
            return
        body = self.rfile.read(length) if length > 0 else b""
        with _lock:
            store_record(record_id, body)
        self._send(204)

    def do_POST(self):
        self._send(405, b"method not allowed")


def main():
    httpd = ThreadingHTTPServer((LISTEN_HOST, LISTEN_PORT), Handler)
    sys.stderr.write("builder-app listening on %s:%d data=%s\n"
                     % (LISTEN_HOST, LISTEN_PORT, DATA_DIR))
    sys.stderr.flush()
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()


if __name__ == "__main__":
    main()

